import 'package:flutter/material.dart';
class AppCard extends StatelessWidget { const AppCard({super.key,required this.child}); final Widget child; @override Widget build(BuildContext context)=>Card(elevation:0,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(18)),child:Padding(padding:const EdgeInsets.all(16),child:child)); }
class PrimaryButton extends StatelessWidget { const PrimaryButton({super.key,required this.label,required this.icon,required this.onPressed}); final String label; final IconData icon; final VoidCallback onPressed; @override Widget build(BuildContext context)=>SizedBox(height:52,width:double.infinity,child:FilledButton.icon(onPressed:onPressed,icon:Icon(icon),label:Text(label))); }
class AppTextField extends StatelessWidget { const AppTextField({super.key,required this.label,required this.icon,this.obscureText=false}); final String label; final IconData icon; final bool obscureText; @override Widget build(BuildContext context)=>TextField(obscureText:obscureText,decoration:InputDecoration(labelText:label,prefixIcon:Icon(icon))); }
class AppLogo extends StatelessWidget { const AppLogo({super.key}); @override Widget build(BuildContext context)=>Center(child:Container(width:64,height:64,decoration:BoxDecoration(borderRadius:BorderRadius.circular(18),color:Theme.of(context).colorScheme.surface,border:Border.all(color:Theme.of(context).colorScheme.primary)),child:Icon(Icons.accessibility_new,color:Theme.of(context).colorScheme.primary,size:36))); }
